  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 120px;
  margin-bottom: 12px;
}
#sprite {
  font-size: 5em;
  animation: float 3s ease-in-out infinite;
  image-rendering: pixelated;
  user-select: none;
  filter: drop-shadow(0 0 8px #f68228);
}
@keyframes float {
  0%,100% { transform: translateY(0); }
  50%      { transform: translateY(-8px); }
}

/* dialogue area */
#dialogue-area {
  flex: 1;
  font-family: "Determination Mono","Share Tech Mono",monospace;
  font-size: 1em;
  line-height: 1.7;
  min-height: 80px;
}
#dialogue-text { white-space: pre-wrap; }
#dialogue-cursor {
  display: inline-block;
  animation: blink 0.6s infinite;
  margin-left: 2px;
}

/* content panels */
#content-panel {
  display: none;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
  max-height: 280px;
  padding-right: 4px;
}
#content-panel::-webkit-scrollbar { width: 4px; }
#content-panel::-webkit-scrollbar-track { background: #000; }
#content-panel::-webkit-scrollbar-thumb { background: #f68228; }

/* ─── STAT BAR (name / LV / HP) ─── */
#stat-bar {
  border: 4px solid #fff;
  padding: 10px 14px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  font-family: MNC,"Crypt of Tomorrow","Arial Black",monospace;
  font-size: 0.78em;
}
#heart-icon { color: #e90111; font-size: 1.2em; }
#char-name  { font-weight: bold; letter-spacing: 1px; }
#lv-label   { color: #f68228; }
.hp-wrap    { display: flex; align-items: center; gap: 8px; flex: 1; }
#hp-bar-bg  {
  flex: 1; height: 14px;
  background: #111;
  border: 2px solid #555;
  position: relative;
  min-width: 80px;
}
#hp-bar-fill {
  height: 100%;
  background: #f68228;
  width: 0%;
  transition: width 1.5s ease;
}
#hp-text    { font-size: 0.9em; white-space: nowrap; }
#flavor-text {
  width: 100%;
  font-family: "Determination Mono","Share Tech Mono",monospace;
  font-size: 0.65em;
  color: #888;
  font-style: italic;
  margin-top: 2px;
}

/* ─── BATTLE BUTTONS ─── */
#battle-buttons {
  border: 4px solid #fff;
  padding: 14px;
  display: flex;
  justify-content: space-around;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.battle-btn {
  font-family: Mercy,"Determination Sans","Share Tech Mono",monospace;
  font-size: 1.1em;
  color: #fff;
  padding: 6px 18px;
  cursor: pointer;
  position: relative;

